<?php
namespace App\Interfaces\Http\Controllers\Api\V1\Claims;
use App\Application\Audit\AuditWriter;use App\Domain\Claims\ClaimStateMachine;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
final class ClaimController{
public function store(Request$r,AuditWriter$audit){$d=$r->validate(['policy_id'=>'required|uuid|exists:policies,id','claimant_party_id'=>'required|uuid|exists:parties,id','loss_occurred_at'=>'required|date|before_or_equal:now','loss_details'=>'required|array','estimated_loss_minor'=>'nullable|integer|min:0']);$tenant=app(\App\Domain\Tenancy\TenantContext::class)->id();$p=DB::table('policies')->where(['id'=>$d['policy_id'],'tenant_id'=>$tenant])->first();abort_unless($p,422,'Policy does not belong to this tenant.');$loss=\Illuminate\Support\Carbon::parse($d['loss_occurred_at']);abort_if($loss->lt(\Illuminate\Support\Carbon::parse($p->coverage_starts_at))||$loss->gt(\Illuminate\Support\Carbon::parse($p->coverage_ends_at)),422,'Loss date falls outside the coverage period.');$id=(string)Str::uuid();$number='CLM-'.now()->format('Ym').'-'.strtoupper(Str::random(8));DB::transaction(function()use($d,$tenant,$id,$number,$r,$audit){DB::table('claims')->insert(['id'=>$id,'tenant_id'=>$tenant,'policy_id'=>$d['policy_id'],'claimant_party_id'=>$d['claimant_party_id'],'claim_number'=>$number,'status'=>'SUBMITTED','loss_occurred_at'=>$d['loss_occurred_at'],'loss_details'=>json_encode($d['loss_details']),'estimated_loss_minor'=>$d['estimated_loss_minor']??null,'currency'=>'XAF','submitted_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('claim_events')->insert(['id'=>(string)Str::uuid(),'claim_id'=>$id,'type'=>'FNOL_SUBMITTED','from_status'=>'DRAFT','to_status'=>'SUBMITTED','reason_code'=>'FNOL','actor_id'=>$r->user()->id,'details'=>'{}','occurred_at'=>now()]);$audit->record('claim.submitted','claim',$id,['claim_number'=>$number]);});return response()->json(['data'=>['id'=>$id,'claim_number'=>$number,'status'=>'SUBMITTED']],201);}
public function show(string$claim){$c=$this->claim($claim);return response()->json(['data'=>['claim'=>$c,'events'=>DB::table('claim_events')->where('claim_id',$claim)->orderBy('occurred_at')->get(),'documents'=>DB::table('claim_documents')->where('claim_id',$claim)->get()]]);}
public function transition(Request$r,string$claim,ClaimStateMachine$machine,AuditWriter$audit){$d=$r->validate(['to_status'=>'required|in:ACKNOWLEDGED,EVIDENCE_PENDING,ASSESSMENT,CARRIER_REVIEW,APPROVED,PARTIALLY_APPROVED,DECLINED,PAID,DISPUTED,CLOSED','reason_code'=>'required|string|max:64','details'=>'sometimes|array']);$c=$this->claim($claim);$machine->assert($c->status,$d['to_status']);DB::transaction(function()use($c,$d,$claim,$r,$audit){$update=['status'=>$d['to_status'],'updated_at'=>now()];if($d['to_status']==='ACKNOWLEDGED')$update['acknowledged_at']=now();if($d['to_status']==='CLOSED')$update['closed_at']=now();DB::table('claims')->where('id',$claim)->update($update);DB::table('claim_events')->insert(['id'=>(string)Str::uuid(),'claim_id'=>$claim,'type'=>'STATUS_CHANGED','from_status'=>$c->status,'to_status'=>$d['to_status'],'reason_code'=>$d['reason_code'],'actor_id'=>$r->user()->id,'details'=>json_encode($d['details']??[]),'occurred_at'=>now()]);$audit->record('claim.transitioned','claim',$claim,['from'=>$c->status,'to'=>$d['to_status']],$d['reason_code']);});return response()->json(['data'=>['id'=>$claim,'status'=>$d['to_status']]]);}
private function claim(string$id):object{$c=DB::table('claims')->where('tenant_id',app(\App\Domain\Tenancy\TenantContext::class)->id())->where('id',$id)->first();abort_unless($c,404);return$c;}}
